new file mode 100644
index 0000000..0764d63
--- /dev/null
+++ b/.claude/skills/bootstrap/templates/apps/web/src/lib/query/index.ts
@@ -0,0 +1,19 @@
+import { isServer, QueryClient } from "@tanstack/react-query";
+
+function makeQueryClient() {
+  // An answer the server read ahead is fresh when the page arrives, so the browser does not ask again at once.
+  return new QueryClient({ defaultOptions: { queries: { staleTime: 60_000 } } });
+}
+
+let browserQueryClient: QueryClient | undefined;
+
+/**
+ * The cache that client components read data through. The server makes a new one for each call, so
+ * no answer crosses from one request into another; the browser keeps one for as long as the page is
+ * open, so an answer read once is not read again by the next component that asks.
+ */
+export function getQueryClient(): QueryClient {
+  if (isServer) return makeQueryClient();
+  browserQueryClient ??= makeQueryClient();
+  return browserQueryClient;
+}
diff --git a/.claude/skills/bootstrap/templates/apps/web/src/lib/query/query-provider.tsx b/.claude/skills/bootstrap/templates/apps/web/src/lib/query/query-provider.tsx
new file mode 100644
index 0000000..9856a88
--- /dev/null
+++ b/.claude/skills/bootstrap/templates/apps/web/src/lib/query/query-provider.tsx
@@ -0,0 +1,11 @@
+"use client";
+
+import { QueryClientProvider } from "@tanstack/react-query";
+import type { ReactNode } from "react";
+
+import { getQueryClient } from "./index";
+
+/** Gives every client component below it the query cache that `useQuery` reads through. */
+export function QueryProvider({ children }: { children: ReactNode }) {
+  return <QueryClientProvider client={getQueryClient()}>{children}</QueryClientProvider>;
+}

